BEGIN;

-- La Armada: banda de hardcore punk y metal formada en Santo Domingo en 2001 y radicada en Chicago desde 2008; no un grupo de hip hop y urbano. El relleno hablaba de 'La Armada Roja'. Fuentes: Wikipedia en inglés (historia, discografía, alineaciones; con citas a Vice, Metal Injection, Remezcla, New Noise Magazine, Maximum Rocknroll), Triunfo Rock (29 sep. 2025: originada en Santo Domingo en 2001, radicada en Chicago), Revista Marvin (30 jun. 2021: formada en RD, se mudó a Chicago), YouTube y sitio oficial de la banda, MusicBrainz ('Rock dominicano'; álbum 'Split' sin fecha). Conflicto: una página de Facebook la da formada en 2003; el resto, 2001. Campos: birth_year 2001, birth_place Santo Domingo / Distrito Nacional (formación), primary_genre rock, genres vacío (urbano era erróneo), tag diaspora. La cifra de 'banda de metal más popular de RD según Spotify' no se usa (regla 6).

UPDATE artists SET birth_year = 2001, birth_place = 'Santo Domingo', province = 'Distrito Nacional', genres = ARRAY[]::text[], artist_tags = ARRAY['secular','diaspora']::text[] WHERE slug = 'la-armada';

INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"La Armada is a hardcore punk and metal band formed in Santo Domingo in 2001 and based in Chicago since 2008, which mixes its music with traditional Dominican and Caribbean rhythms and sings in Spanish and English."}]},{"type":"paragraph","content":[{"type":"text","text":"Santo Domingo","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The band began in the capital with the bassist Alberto “Mani” Marte, the drummer Luis Martínez, the guitarists Paúl Rivera and Jonathan Salazar and the singer Javier Fernández. The punk and metal scene of the country was small, so they booked bands and organized shows wherever they could find a space, in abandoned buildings and backyards."}]},{"type":"paragraph","content":[{"type":"text","text":"Chicago","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"To find more opportunities as a hardcore band, La Armada relocated to the United States: Marte moved to Florida in 2004 and the rest of the band joined him. In 2006 the band opened for Los Crudos at a Latino punk festival in Chicago, and by 2008 it was based in the city. There it released a self-titled album on Fat Sandwich Records in 2012, the EP «Crisis» in 2014 and «Anti-Colonial Vol. 1» on Creep Records in 2018. Its lyrics deal with colonialism, capitalism, immigration and racism, and the band calls its style “Latino Hardcore Fury”."}]},{"type":"paragraph","content":[{"type":"text","text":"Recent years","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The band had to cancel a European tour because of the COVID-19 pandemic. Javier Fernández left in 2019 and was replaced by the singer Casper Torres, who debuted on the EP «Songs of the Exiled I: Chicago» (2020); the series was dropped and the band released the EP «Opías» in 2021, and in 2022 the album «Anti-Colonial Vol. 2», on Lockjaw Records, Thousand Islands Records and Mal De Ojo Records. Eric Urrea became its drummer, and in September 2024 the single «500 años» introduced Enrique “Quique” Vargas as lead singer. The band has toured with Propagandhi, Iron Chic, Sick of It All and Death by Stereo."}]},{"type":"paragraph","content":[{"type":"text","text":"Legacy","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"La Armada is one of the Dominican hardcore bands that built a career abroad, in the punk circuit of Chicago, while keeping its Dominican identity in its language, its themes and its rhythms."}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'la-armada'
ON CONFLICT (document_type, owner_artist_id, locale) WHERE document_type = 'artist_biography' DO UPDATE
   SET document = excluded.document, status = 'published', revision = editorial_documents.revision + 1, updated_at = now();
DELETE FROM editorial_entity_references WHERE editorial_document_id IN
  (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
    WHERE a.slug = 'la-armada' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'La Armada is a hardcore punk and metal band formed in Santo Domingo in 2001 and based in Chicago since 2008, which mixes its music with traditional Dominican and Caribbean rhythms and sings in Spanish and English.

**Santo Domingo**

The band began in the capital with the bassist Alberto “Mani” Marte, the drummer Luis Martínez, the guitarists Paúl Rivera and Jonathan Salazar and the singer Javier Fernández. The punk and metal scene of the country was small, so they booked bands and organized shows wherever they could find a space, in abandoned buildings and backyards.

**Chicago**

To find more opportunities as a hardcore band, La Armada relocated to the United States: Marte moved to Florida in 2004 and the rest of the band joined him. In 2006 the band opened for Los Crudos at a Latino punk festival in Chicago, and by 2008 it was based in the city. There it released a self-titled album on Fat Sandwich Records in 2012, the EP «Crisis» in 2014 and «Anti-Colonial Vol. 1» on Creep Records in 2018. Its lyrics deal with colonialism, capitalism, immigration and racism, and the band calls its style “Latino Hardcore Fury”.

**Recent years**

The band had to cancel a European tour because of the COVID-19 pandemic. Javier Fernández left in 2019 and was replaced by the singer Casper Torres, who debuted on the EP «Songs of the Exiled I: Chicago» (2020); the series was dropped and the band released the EP «Opías» in 2021, and in 2022 the album «Anti-Colonial Vol. 2», on Lockjaw Records, Thousand Islands Records and Mal De Ojo Records. Eric Urrea became its drummer, and in September 2024 the single «500 años» introduced Enrique “Quique” Vargas as lead singer. The band has toured with Propagandhi, Iron Chic, Sick of It All and Death by Stereo.

**Legacy**

La Armada is one of the Dominican hardcore bands that built a career abroad, in the punk circuit of Chicago, while keeping its Dominican identity in its language, its themes and its rhythms.' WHERE slug = 'la-armada';

